import pytest
from freebusy import free_slots

WEEK = ("mon", "tue", "wed", "thu", "fri")
WEEKDAYS = ("mon", "tue", "wed", "thu", "fri", "sat", "sun")


class TestBasicFunctionality:
    """Test basic free slots calculation."""

    def test_single_attendee_simple(self):
        """Single attendee within working hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_single_attendee_full_week(self):
        """Single attendee working full week."""
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-06T00:00Z", 60)
        expected = [
            ("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z"),
            ("2025-06-03T09:00:00Z", "2025-06-03T17:00:00Z"),
            ("2025-06-04T09:00:00Z", "2025-06-04T17:00:00Z"),
            ("2025-06-05T09:00:00Z", "2025-06-05T17:00:00Z"),
        ]
        assert result == expected

    def test_single_attendee_no_hours_today(self):
        """Single attendee with no working hours on a specific day."""
        alice = {"tz": "UTC", "hours": {"tue": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # 2025-06-02 is Monday, no working hours
        assert result == []

    def test_no_free_time(self):
        """No free time in search window."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-10:00"]}}
        result = free_slots([alice], "2025-06-02T10:00Z", "2025-06-02T17:00Z", 30)
        assert result == []

    def test_free_slot_smaller_than_min_minutes(self):
        """Slot exists but is smaller than min_minutes."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        # Exact slot is 480 minutes, so 500 min_minutes should exclude it
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 500)
        assert result == []


class TestMultipleAttendees:
    """Test scheduling with multiple attendees."""

    def test_two_attendees_same_timezone(self):
        """Two attendees in the same timezone."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        bob = {"tz": "UTC", "hours": {"mon": ["10:00-15:00"]}}
        result = free_slots([alice, bob], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # Overlap is 10:00-15:00
        assert result == [("2025-06-02T10:00:00Z", "2025-06-02T15:00:00Z")]

    def test_two_attendees_different_timezones(self):
        """Two attendees in different timezones."""
        # NY is UTC-4 in June, Berlin is UTC+2
        ny = {"tz": "America/New_York", "hours": {"mon": ["09:00-17:00"]}}
        berlin = {"tz": "Europe/Berlin", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([ny, berlin], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # NY 09:00-17:00 EDT = 13:00-21:00 UTC
        # Berlin 09:00-17:00 CEST = 07:00-15:00 UTC
        # Overlap = 13:00-15:00 UTC
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T15:00:00Z")]

    def test_three_attendees_different_hours(self):
        """Three attendees with different working hours."""
        a1 = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        a2 = {"tz": "UTC", "hours": {"mon": ["10:00-16:00"]}}
        a3 = {"tz": "UTC", "hours": {"mon": ["11:00-15:00"]}}
        result = free_slots([a1, a2, a3], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # Intersection is 11:00-15:00
        assert result == [("2025-06-02T11:00:00Z", "2025-06-02T15:00:00Z")]

    def test_attendees_no_overlap(self):
        """Multiple attendees with no overlapping working hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-12:00"]}}
        bob = {"tz": "UTC", "hours": {"mon": ["14:00-17:00"]}}
        result = free_slots([alice, bob], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == []


class TestWorkingHoursFormats:
    """Test various working hours formats and edge cases."""

    def test_hours_spanning_midnight_forward(self):
        """Working hours span midnight (e.g., 22:00-06:00)."""
        alice = {"tz": "UTC", "hours": {"fri": ["22:00-06:00"]}}
        # Friday 22:00 to Saturday 06:00
        # Friday 2025-06-06 22:00 UTC to Saturday 2025-06-07 06:00 UTC
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-08T00:00Z", 30)
        assert result == [("2025-06-06T22:00:00Z", "2025-06-07T06:00:00Z")]

    def test_hours_with_24_00_end(self):
        """Working hours ending with 24:00."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-24:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # Monday 09:00 to Tuesday 00:00
        assert result == [("2025-06-02T09:00:00Z", "2025-06-03T00:00:00Z")]

    def test_multiple_hours_entries_same_day(self):
        """Multiple working hours entries on the same day."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-12:00", "14:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        expected = [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T14:00:00Z", "2025-06-02T17:00:00Z"),
        ]
        assert result == expected

    def test_overlapping_hours_entries(self):
        """Overlapping working hours entries on the same day."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-15:00", "12:00-18:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # Both entries cover the entire 09:00-18:00 period
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T18:00:00Z")]

    def test_hours_single_minute(self):
        """Working hours spanning a single minute."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-09:01"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T09:01:00Z")]

    def test_hours_starting_at_midnight(self):
        """Working hours starting at midnight."""
        alice = {"tz": "UTC", "hours": {"mon": ["00:00-12:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T00:00:00Z", "2025-06-02T12:00:00Z")]

    def test_hours_ending_at_midnight(self):
        """Working hours ending at midnight."""
        alice = {"tz": "UTC", "hours": {"mon": ["12:00-24:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T12:00:00Z", "2025-06-03T00:00:00Z")]


class TestBusyPeriods:
    """Test busy period filtering."""

    def test_busy_period_no_overlap(self):
        """Busy period outside working hours."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T17:00:00Z", "2025-06-02T18:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_busy_period_covers_all_working_hours(self):
        """Busy period covers entire working hours."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == []

    def test_busy_period_partial_overlap(self):
        """Busy period partially overlaps working hours."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00:00Z", "2025-06-02T14:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        expected = [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T14:00:00Z", "2025-06-02T17:00:00Z"),
        ]
        assert result == expected

    def test_multiple_busy_periods(self):
        """Multiple busy periods."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T11:00:00Z"],
                ["2025-06-02T13:00:00Z", "2025-06-02T15:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        expected = [
            ("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z"),
            ("2025-06-02T11:00:00Z", "2025-06-02T13:00:00Z"),
            ("2025-06-02T15:00:00Z", "2025-06-02T17:00:00Z"),
        ]
        assert result == expected

    def test_busy_period_extends_outside_search_window_start(self):
        """Busy period starts before search window."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T08:00:00Z", "2025-06-02T12:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        expected = [("2025-06-02T12:00:00Z", "2025-06-02T17:00:00Z")]
        assert result == expected

    def test_busy_period_extends_outside_search_window_end(self):
        """Busy period ends after search window."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T14:00:00Z", "2025-06-02T18:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        expected = [("2025-06-02T09:00:00Z", "2025-06-02T14:00:00Z")]
        assert result == expected

    def test_busy_period_different_timezone(self):
        """Busy period specified in attendee's timezone."""
        alice = {
            "tz": "America/New_York",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00:00-04:00", "2025-06-02T14:00:00-04:00"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # NY 09:00-17:00 EDT = 13:00-21:00 UTC
        # Busy 12:00-14:00 EDT = 16:00-18:00 UTC
        expected = [
            ("2025-06-02T13:00:00Z", "2025-06-02T16:00:00Z"),
            ("2025-06-02T18:00:00Z", "2025-06-02T21:00:00Z"),
        ]
        assert result == expected

    def test_no_busy_periods(self):
        """Attendee has no busy periods."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_touching_busy_periods(self):
        """Adjacent busy periods."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T12:00:00Z"],
                ["2025-06-02T12:00:00Z", "2025-06-02T14:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        expected = [
            ("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z"),
            ("2025-06-02T14:00:00Z", "2025-06-02T17:00:00Z"),
        ]
        assert result == expected


class TestMinutesFiltering:
    """Test min_minutes parameter."""

    def test_min_minutes_one(self):
        """Minimum minutes is 1."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-09:01"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T09:01:00Z")]

    def test_min_minutes_exact_boundary(self):
        """Slot duration equals min_minutes."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-10:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Exactly 60 minutes
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z")]

    def test_min_minutes_one_less_than_slot(self):
        """Slot duration is one more than min_minutes."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-10:01"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # 61 minutes, includes slot
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T10:01:00Z")]

    def test_min_minutes_one_more_than_slot(self):
        """Slot duration is one less than min_minutes."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-09:59"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # 59 minutes, excludes slot
        assert result == []

    def test_min_minutes_multiple_slots(self):
        """Filter multiple slots by min_minutes."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T10:30:00Z"],
                ["2025-06-02T12:00:00Z", "2025-06-02T12:15:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # 09:00-10:00 (60 min, included)
        # 10:30-12:00 (90 min, included)
        # 12:15-17:00 (285 min, included)
        expected = [
            ("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z"),
            ("2025-06-02T10:30:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T12:15:00Z", "2025-06-02T17:00:00Z"),
        ]
        assert result == expected


class TestTimestampFormats:
    """Test various timestamp formats."""

    def test_timestamp_with_seconds(self):
        """Timestamps with seconds component."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots(
            [alice], "2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z", 30
        )
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z")]

    def test_timestamp_no_seconds(self):
        """Timestamps without seconds component."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T10:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z")]

    def test_timestamp_positive_offset(self):
        """Timestamps with positive UTC offset."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots(
            [alice], "2025-06-02T13:00:00+04:00", "2025-06-02T14:00:00+04:00", 30
        )
        # +04:00 = 09:00 UTC to 10:00 UTC
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z")]

    def test_timestamp_negative_offset(self):
        """Timestamps with negative UTC offset."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots(
            [alice], "2025-06-02T05:00:00-04:00", "2025-06-02T06:00:00-04:00", 30
        )
        # -04:00 = 09:00 UTC to 10:00 UTC
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z")]

    def test_timestamp_non_standard_offset(self):
        """Timestamps with non-standard offset like +05:45."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots(
            [alice], "2025-06-02T14:45:00+05:45", "2025-06-02T15:45:00+05:45", 30
        )
        # +05:45 = 09:00 UTC to 10:00 UTC
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z")]

    def test_timestamp_z_format(self):
        """Timestamps with Z format."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T10:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z")]


class TestDaylightSavingTime:
    """Test daylight saving time transitions."""

    def test_dst_spring_forward_ny(self):
        """DST spring forward in America/New_York (2025-03-09)."""
        # On 2025-03-09 at 02:00 EST, clocks jump to 03:00 EDT
        alice = {"tz": "America/New_York", "hours": {"sun": ["02:00-04:00"]}}
        result = free_slots([alice], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 30)
        # 02:00-04:00 EST doesn't exist, but 03:00-04:00 EDT does
        # 03:00-04:00 EDT = 07:00-08:00 UTC
        assert result == [("2025-03-09T07:00:00Z", "2025-03-09T08:00:00Z")]

    def test_dst_spring_forward_skipped_time(self):
        """Working hours entry in skipped time (spring forward)."""
        # 2025-03-09: clocks jump from 02:00 EST to 03:00 EDT
        alice = {"tz": "America/New_York", "hours": {"sun": ["02:10-02:50"]}}
        result = free_slots([alice], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 1)
        # This time is skipped, so no coverage
        assert result == []

    def test_dst_fall_back_ny(self):
        """DST fall back in America/New_York (2025-11-02)."""
        # On 2025-11-02 at 02:00 EDT, clocks fall back to 01:00 EST
        alice = {"tz": "America/New_York", "hours": {"sun": ["00:00-03:00"]}}
        result = free_slots([alice], "2025-11-02T00:00Z", "2025-11-03T00:00Z", 1)
        # 00:00-03:00 EDT = 04:00-08:00 UTC
        # 00:00-03:00 EST (repeated) = 05:00-08:00 UTC
        # Total = 04:00-06:00 UTC (EDT) + 05:00-08:00 UTC (EST, repeated)
        # Wall clock shows both, so covered twice
        assert len(result) >= 1
        assert result[0][0] == "2025-11-02T04:00:00Z"


class TestMultipleDays:
    """Test slots spanning multiple days."""

    def test_slot_spanning_two_days(self):
        """Overnight working hours spanning two days."""
        alice = {"tz": "UTC", "hours": {"mon": ["22:00-24:00"], "tue": ["00:00-02:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-04T00:00Z", 30)
        # Monday 22:00 to Tuesday 00:00 (covered by mon and tue entries)
        expected = [("2025-06-02T22:00:00Z", "2025-06-03T02:00:00Z")]
        assert result == expected

    def test_no_splitting_at_day_boundaries(self):
        """Free time spanning day boundary shouldn't be split."""
        alice = {"tz": "UTC", "hours": {"sun": ["20:00-24:00"], "mon": ["00:00-04:00"]}}
        result = free_slots([alice], "2025-06-01T00:00Z", "2025-06-03T00:00Z", 1)
        # Sunday 20:00 UTC to Monday 04:00 UTC (continuous via midnight)
        expected = [("2025-06-01T20:00:00Z", "2025-06-02T04:00:00Z")]
        assert result == expected

    def test_multiple_free_slots_different_days(self):
        """Multiple free slots on different days."""
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-07T00:00Z", 60)
        expected = [
            ("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z"),
            ("2025-06-03T09:00:00Z", "2025-06-03T17:00:00Z"),
            ("2025-06-04T09:00:00Z", "2025-06-04T17:00:00Z"),
            ("2025-06-05T09:00:00Z", "2025-06-05T17:00:00Z"),
            ("2025-06-06T09:00:00Z", "2025-06-06T17:00:00Z"),
        ]
        assert result == expected


class TestEdgeCases:
    """Test edge cases and boundary conditions."""

    def test_start_equals_busy_start(self):
        """Search window starts at busy period start."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00:00Z", "2025-06-02T14:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T12:00:00Z", "2025-06-02T17:00Z", 30)
        # Busy period blocks 12:00-14:00
        assert result == [("2025-06-02T14:00:00Z", "2025-06-02T17:00:00Z")]

    def test_end_equals_busy_end(self):
        """Search window ends at busy period end."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
