import pytest
from freebusy import free_slots

WEEK = ("mon", "tue", "wed", "thu", "fri")
WEEKEND = ("sat", "sun")


class TestBasicFunctionality:
    """Tests for basic free_slots functionality."""

    def test_single_attendee_no_busy(self):
        """Single attendee, no busy periods, entire working hours are free."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_single_attendee_weekday_range(self):
        """Single attendee working Mon-Fri."""
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-07T00:00Z", 60)
        # Mon-Fri are 2025-06-02 (Mon) to 2025-06-06 (Fri)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z"),
            ("2025-06-03T09:00:00Z", "2025-06-03T17:00:00Z"),
            ("2025-06-04T09:00:00Z", "2025-06-04T17:00:00Z"),
            ("2025-06-05T09:00:00Z", "2025-06-05T17:00:00Z"),
            ("2025-06-06T09:00:00Z", "2025-06-06T17:00:00Z"),
        ]

    def test_no_working_hours_on_a_day(self):
        """Days without working hours entries yield no free slots."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-04T00:00Z", 60)
        # Only Monday 2025-06-02 has working hours
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_working_hours_empty_list_means_no_hours(self):
        """Empty list of hours for a day means no working hours."""
        alice = {"tz": "UTC", "hours": {"mon": [], "tue": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-04T00:00Z", 60)
        # Only Tuesday has working hours
        assert result == [("2025-06-03T09:00:00Z", "2025-06-03T17:00:00Z")]


class TestMultipleAttendees:
    """Tests for multiple attendees."""

    def test_two_attendees_same_timezone(self):
        """Two attendees in same timezone."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        bob = {"tz": "UTC", "hours": {"mon": ["10:00-16:00"]}}
        result = free_slots([alice, bob], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Both must work: 10:00-16:00
        assert result == [("2025-06-02T10:00:00Z", "2025-06-02T16:00:00Z")]

    def test_two_attendees_different_timezones(self):
        """Two attendees in different timezones."""
        ny = {"tz": "America/New_York", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        berlin = {"tz": "Europe/Berlin", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([ny, berlin], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # NY: 2025-06-02 09:00-17:00 EDT (UTC-4) = 13:00-21:00Z
        # Berlin: 2025-06-02 09:00-17:00 CEST (UTC+2) = 07:00-15:00Z
        # Overlap: 13:00-15:00Z
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T15:00:00Z")]

    def test_three_attendees_overlapping_hours(self):
        """Three attendees with increasingly restrictive working hours."""
        a = {"tz": "UTC", "hours": {"mon": ["08:00-18:00"]}}
        b = {"tz": "UTC", "hours": {"mon": ["10:00-16:00"]}}
        c = {"tz": "UTC", "hours": {"mon": ["11:00-15:00"]}}
        result = free_slots([a, b, c], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Intersection: 11:00-15:00
        assert result == [("2025-06-02T11:00:00Z", "2025-06-02T15:00:00Z")]

    def test_no_overlap_between_attendees(self):
        """Two attendees with no overlapping working hours."""
        a = {"tz": "UTC", "hours": {"mon": ["08:00-12:00"]}}
        b = {"tz": "UTC", "hours": {"mon": ["13:00-17:00"]}}
        result = free_slots([a, b], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        assert result == []

    def test_one_attendee_no_hours_for_day(self):
        """One attendee has no working hours for a given day."""
        a = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        b = {"tz": "UTC", "hours": {"tue": ["09:00-17:00"]}}
        result = free_slots([a, b], "2025-06-02T00:00Z", "2025-06-04T00:00Z", 60)
        # No overlap: a only works Monday, b only works Tuesday
        assert result == []


class TestBusyPeriods:
    """Tests for busy period handling."""

    def test_single_busy_period(self):
        """Single busy period removes time from free slot."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00:00Z", "2025-06-02T14:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Working: 09:00-17:00; Busy: 12:00-14:00
        # Free: 09:00-12:00 and 14:00-17:00 (both >= 60 min)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T14:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_multiple_overlapping_busy_periods(self):
        """Multiple busy periods that overlap."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-18:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T12:00:00Z"],
                ["2025-06-02T11:00:00Z", "2025-06-02T13:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Busy periods merge: 10:00-13:00
        # Free: 09:00-10:00 (< 60 min, filtered) and 13:00-18:00
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T18:00:00Z")]

    def test_busy_touching_busy(self):
        """Adjacent busy periods."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-18:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T12:00:00Z"],
                ["2025-06-02T12:00:00Z", "2025-06-02T14:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Merged busy: 10:00-14:00
        # Free: 09:00-10:00 (< 60 min) and 14:00-18:00
        assert result == [("2025-06-02T14:00:00Z", "2025-06-02T18:00:00Z")]

    def test_busy_period_spans_working_hours(self):
        """Busy period completely covers working hours."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T08:00:00Z", "2025-06-02T18:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        assert result == []

    def test_busy_period_outside_window(self):
        """Busy period outside search window is ignored."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-01T10:00:00Z", "2025-06-01T12:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Busy period is on 2025-06-01, search is 2025-06-02
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_busy_offset_format_positive(self):
        """Busy period with positive UTC offset."""
        tokyo = {
            "tz": "Asia/Tokyo",
            "hours": {"mon": ["09:00-18:00"]},
            "busy": [["2025-06-02T12:00:00+09:00", "2025-06-02T13:00:00+09:00"]],
        }
        result = free_slots([tokyo], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # 12:00+09:00 = 03:00Z, 13:00+09:00 = 04:00Z
        # Tokyo 09:00-18:00 = 00:00-09:00Z
        # Busy: 03:00-04:00Z
        # Free: 00:00-03:00Z (< 60 min) and 04:00-09:00Z
        assert result == [("2025-06-02T04:00:00Z", "2025-06-02T09:00:00Z")]

    def test_busy_offset_format_negative(self):
        """Busy period with negative UTC offset."""
        ny = {
            "tz": "America/New_York",
            "hours": {"mon": ["09:00-18:00"]},
            "busy": [["2025-06-02T12:00:00-04:00", "2025-06-02T13:00:00-04:00"]],
        }
        result = free_slots([ny], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # 12:00-04:00 = 16:00Z, 13:00-04:00 = 17:00Z
        # NY 09:00-18:00 EDT = 13:00-22:00Z
        # Busy: 16:00-17:00Z
        # Free: 13:00-16:00Z and 17:00-22:00Z
        assert result == [
            ("2025-06-02T13:00:00Z", "2025-06-02T16:00:00Z"),
            ("2025-06-02T17:00:00Z", "2025-06-02T22:00:00Z"),
        ]


class TestMinutesFilter:
    """Tests for minimum minutes filtering."""

    def test_min_minutes_30(self):
        """Filter out slots shorter than 30 minutes."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-18:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T10:20:00Z"],
                ["2025-06-02T12:00:00Z", "2025-06-02T12:30:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # Free: 09:00-10:00 (60 min), 10:20-12:00 (100 min), 12:30-18:00
        # With min_minutes=30, 09:00-10:00, 10:20-12:00, 12:30-18:00 all qualify
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z"),
            ("2025-06-02T10:20:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T12:30:00Z", "2025-06-02T18:00:00Z"),
        ]

    def test_min_minutes_120(self):
        """Filter to only slots >= 120 minutes."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-18:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T10:30:00Z"],
                ["2025-06-02T12:00:00Z", "2025-06-02T13:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 120)
        # Free: 09:00-10:00 (60 min, filtered), 10:30-12:00 (90 min, filtered), 13:00-18:00 (300 min)
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T18:00:00Z")]

    def test_min_minutes_1(self):
        """Minimum minutes of 1 includes very short slots."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-18:00"]},
            "busy": [["2025-06-02T12:00:00Z", "2025-06-02T12:01:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        # Free: 09:00-12:00 and 12:01-18:00, both included
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T12:01:00Z", "2025-06-02T18:00:00Z"),
        ]

    def test_min_minutes_exceeds_all_slots(self):
        """When all slots are shorter than min_minutes, return empty."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-10:00"]},
            "busy": [["2025-06-02T09:30:00Z", "2025-06-02T09:40:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Free: 09:00-09:30 (30 min), 09:40-10:00 (20 min), neither >= 60 min
        assert result == []


