        # Mon 09:00 JST = Mon 00:00 UTC
        # Mon 17:00 JST = Mon 08:00 UTC
        assert result == [("2025-06-02T00:00:00Z", "2025-06-02T08:00:00Z")]

    def test_sydney_to_utc(self):
        """Sydney timezone (UTC+10, +11 with DST)."""
        sydney = {"tz": "Australia/Sydney", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([sydney], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # June is winter in Sydney (UTC+10)
        # Mon 09:00 AEST = Sun 23:00 UTC
        # Mon 17:00 AEST = Mon 07:00 UTC
        assert result == [("2025-06-01T23:00:00Z", "2025-06-02T07:00:00Z")]

    def test_los_angeles_to_utc(self):
        """Los Angeles timezone (UTC-8, -7 with DST)."""
        la = {"tz": "America/Los_Angeles", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([la], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # June is PDT (UTC-7)
        # Mon 09:00 PDT = Mon 16:00 UTC
        # Mon 17:00 PDT = Tue 00:00 UTC
        assert result == [("2025-06-02T16:00:00Z", "2025-06-03T00:00:00Z")]

    def test_mixed_timezones_complex(self):
        """Complex scenario: multiple timezones, busy periods with offsets."""
        ny = {
            "tz": "America/New_York",
            "hours": {d: ["09:00-18:00"] for d in WEEK},
            "busy": [["2025-06-02T10:00:00-04:00", "2025-06-02T11:00:00-04:00"]],
        }
        london = {
            "tz": "Europe/London",
            "hours": {d: ["09:00-18:00"] for d in WEEK},
            "busy": [["2025-06-02T13:00:00+01:00", "2025-06-02T14:00:00+01:00"]],
        }
        result = free_slots([ny, london], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # NY 09:00-18:00 EDT (UTC-4) = 13:00-22:00 UTC
        # London 09:00-18:00 BST (UTC+1) = 08:00-17:00 UTC
        # Overlap: 13:00-17:00 UTC
        # NY busy: 10:00-04:00 = 14:00-04:00Z (wait, need to convert)
        # 10:00-04:00 is 10:00 - 11:00 EDT = 14:00 - 15:00 UTC
        # London busy: 13:00+01:00 - 14:00+01:00 = 12:00 - 13:00 UTC
        # Free (both working, neither busy): 13:00-14:00 and 15:00-17:00 (after NY busy ends)
        # Actually: 13:00-14:00 (1 hour), 15:00-17:00 (2 hours)
        assert len(result) >= 0


