class TestDaylightSavingTime:
    """Test daylight saving time edge cases."""

    def test_spring_forward_skipped_time(self):
        """Spring forward: working hours covering skipped time are adjusted."""
        # On 2025-03-09 at 02:00 EST, clocks jump to 03:00 EDT (skip 02:00-03:00)
        alice = {"tz": "America/New_York", "hours": {"sun": ["02:30-04:00"]}}
        result = free_slots([alice], "2025-03-09T06:30Z", "2025-03-09T08:30Z", 30)
        # The 02:30-04:00 entry doesn't exist on the wall clock (02:30 is skipped)
        # 03:00-04:00 EDT = 07:00-08:00 UTC
        # But if 02:30 is specified, nothing covers it
        # Actually 02:30 is skipped so never shown; 04:00 EDT = 08:00 UTC
        # So 02:30-04:00 should map to nothing (or the overlap with actual times)
        # Let me reconsider: if someone says they work 02:30-04:00 on a day when 02:30 is skipped,
        # the wall clock jumps from 01:59 EST to 03:00 EDT
        # So 02:30 is never shown, but 03:00-04:00 is shown
        # This requires the implementation to handle this correctly
        assert result == []

    def test_spring_forward_afternoon_hours(self):
        """Spring forward: afternoon hours unaffected."""
        alice = {"tz": "America/New_York", "hours": {"sun": ["14:00-18:00"]}}
        result = free_slots([alice], "2025-03-09T18:00Z", "2025-03-09T22:00Z", 30)
        # 14:00-18:00 EDT = 18:00-22:00 UTC
        assert result == [("2025-03-09T18:00:00Z", "2025-03-09T22:00:00Z")]

    def test_spring_forward_overnight_crossing(self):
        """Spring forward: overnight hours crossing the DST transition."""
        # 22:00 EST Saturday to 06:00 EDT Sunday
        # At 02:00 EST (07:00 UTC), clocks jump to 03:00 EDT (07:00 UTC)
        alice = {"tz": "America/New_York", "hours": {"sat": ["22:00-06:00"]}}
        result = free_slots([alice], "2025-03-08T02:00Z", "2025-03-09T10:00Z", 30)
        # Sat 22:00 EST = Sat 03:00 UTC (not 02:00 UTC, since EST = UTC-5)
        # Wait, Saturday is earlier. Let me recalculate.
        # In winter (before 2025-03-09), America/New_York is EST (UTC-5)
        # So Saturday 22:00 EST = Saturday 03:00 UTC (next day)
        # This continues through Sunday morning until the transition
        # Let me verify the dates: 2025-03-09 is Sunday; the transition happens at 02:00 EST (07:00 UTC)
        # Saturday 22:00 EST = Sat 3:00 UTC, Sat 23:00 EST = Sat 4:00 UTC, Sun 0:00 EST = Sun 5:00 UTC
        # Sun 1:00 EST = Sun 6:00 UTC, Sun 2:00 EST doesn't exist (jumps to 3:00 EDT)
        # So the entry "22:00-06:00" under Saturday covers Sat 22:00 EST to Sun 06:00 EDT
        # In UTC: Sat 3:00 UTC to Sun 11:00 UTC (since Sun 06:00 EDT = Sun 10:00 UTC... wait EDT is UTC-4)
        # EDT is UTC-4, so Sun 06:00 EDT = Sun 10:00 UTC
        # So the period is Sat 3:00 UTC to Sun 10:00 UTC
        result = free_slots([alice], "2025-03-08T02:00Z", "2025-03-09T11:00Z", 30)
        assert result == [("2025-03-08T03:00:00Z", "2025-03-09T10:00:00Z")]

    def test_fall_back_repeated_time(self):
        """Fall back: repeated times are covered twice."""
        # On 2025-11-02 at 02:00 EDT, clocks fall back to 01:00 EST
        # So 01:00-01:59 is shown twice
        alice = {"tz": "America/New_York", "hours": {"sun": ["01:00-03:00"]}}
        result = free_slots([alice], "2025-11-02T05:00Z", "2025-11-02T08:00Z", 30)
        # 01:00-03:00 EDT = 05:00-07:00 UTC (before fall back)
        # 01:00-03:00 EST = 06:00-08:00 UTC (after fall back)
        # So the entry covers 05:00-07:00 UTC and 06:00-08:00 UTC
        # Union is 05:00-08:00 UTC
        assert result == [("2025-11-02T05:00:00Z", "2025-11-02T08:00:00Z")]

    def test_fall_back_ambiguous_time_specific_period(self):
        """Fall back: period that includes repeated time."""
        alice = {"tz": "America/New_York", "hours": {"sun": ["00:00-03:00"]}}
        result = free_slots([alice], "2025-11-02T04:00Z", "2025-11-02T09:00Z", 30)
        # 00:00-03:00 EDT = 04:00-07:00 UTC
        # 00:00-03:00 EST = 05:00-08:00 UTC
        # Union is 04:00-08:00 UTC (not continuous; there's EDT and EST coverage)
        # Actually, since these are repeated times, both intervals apply
        # So free time is 04:00-08:00 UTC
        assert result == [("2025-11-02T04:00:00Z", "2025-11-02T08:00:00Z")]


