class TestMaximalPeriods:
    """Test that results are maximal (not split unnecessarily)."""

    def test_no_splitting_at_day_boundary(self):
        """Free time spanning multiple days is not split."""
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-02T10:00Z", "2025-06-04T16:00Z", 30)
        # Should be one continuous period if the entire span is free
        # Actually, there are non-working hours (17:00-09:00 each day)
        # So results should be:
        assert result == [
            ("2025-06-02T10:00:00Z", "2025-06-02T17:00:00Z"),
            ("2025-06-03T09:00:00Z", "2025-06-03T17:00:00Z"),
            ("2025-06-04T09:00:00Z", "2025-06-04T16:00:00Z"),
        ]

    def test_no_splitting_at_working_hours_boundary(self):
        """Adjacent working-hour entries merge into one slot."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-13:00", "13:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T08:00Z", "2025-06-02T18:00Z", 30)
        # Even though there are two entries, they form one continuous slot
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_no_splitting_at_timezone_boundary(self):
        """Free time doesn't split at timezone conversions."""
        alice = {"tz": "UTC", "hours": {d: ["00:00-24:00"] for d in ALL_DAYS}}
        bob = {"tz": "Europe/Berlin", "hours": {d: ["00:00-24:00"] for d in ALL_DAYS}}
        result = free_slots([alice, bob], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Both work 24/7, so entire period is free
        assert result == [("2025-06-02T00:00:00Z", "2025-06-03T00:00:00Z")]


class TestComplexScenarios:
    """Test complex, realistic scenarios."""

    def test_global_team_coordination(self):
        """Find common time for distributed team across multiple zones."""
        members = [
            {"tz": "America/New_York", "hours": {d: ["09:00-17:00"] for d in WEEK}},
            {"tz": "Europe/London", "hours": {d: ["09:00-17:00"] for d in WEEK}},
            {"tz": "Asia/Singapore", "hours": {d: ["09:00-17:00"] for d in WEEK}},
        ]
        # In June:
        # NY is EDT (UTC-4): 09:00-17:00 = 13:00-21:00 UTC
        # London is BST (UTC+1): 09:00-17:00 = 08:00-16:00 UTC
        # Singapore is SGT (UTC+8): 09:00-17:00 = 01:00-09:00 UTC
        # Overlap: 13:00-16:00 UTC (3 hours)
        result = free_slots(members, "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # Only Monday has slots
        assert len(result) >= 1
        # Verify there's at least one 1-hour slot
        assert any((end_dt.timestamp() - start_dt.timestamp()) >= 3600 
                  for start_dt, end_dt in 
                  [(f"{s}".replace("Z", "+00:00"), f"{e}".replace("Z", "+00:00")) 
                   for s, e in result])

    def test_attendee_with_many_busy_periods(self):
        """Attendee with many scattered busy meetings."""
        busy_periods = [
            ["2025-06-02T10:00:00Z", "2025-06-02T10:30:00Z"],
            ["2025-06-02T11:00:00Z", "2025-06-02T11:30:00Z"],
            ["2025-06-02T13:00:00Z", "2025-06-02T14:00:00Z"],
            ["2025-06-02T15:00:00Z", "2025-06-02T15:15:00Z"],
        ]
        alice = {
            "tz": "UTC",
            "hours": {d: ["09:00-17:00"] for d in WEEK},
            "busy": busy_periods,
        }
        result = free_slots([alice], "2025-06-02T08:00Z", "2025-06-02T18:00Z", 30)
        # Should have 5 free slots (before 10:00, 10:30-11:00, 11:30-13:00, 14:00-15:00, 15:15-17:00)
        # But need >= 30 minutes
        assert len(result) == 2  # 10:30-11:00 (30 min), 11:30-13:00 (90 min), 14:00-15:00 (60 min), 15:15-17:00 (105 min), 09:00-10:00 (60 min)
